<?php
defined('ABSPATH')||exit; class CFP_Upsell{public function hooks():void{add_action('admin_post_nopriv_cfp_upsell_accept',array($this,'accept')); add_action('admin_post_cfp_upsell_accept',array($this,'accept'));} public function accept():void{$order_id=absint($_GET['order_id']??0); $product_id=absint($_GET['product_id']??0); $token=sanitize_text_field(wp_unslash($_GET['token']??'')); if(!hash_equals(CFP_Security::token(array($order_id,$product_id)),$token)){wp_die('Invalid token',403);} $order=wc_get_order($order_id); $product=wc_get_product($product_id); if($order&&$product){$order->add_product($product,1); $order->calculate_totals(); $order->add_order_note(__('ConversionFlow upsell accepted.','conversionflow-pro')); (new CFP_Tracking())->track('upsell_accepted',0,0,$order_id,$order->get_billing_email(),(float)$product->get_price());} wp_safe_redirect($order?$order->get_checkout_order_received_url():home_url('/')); exit;}}
